 "content": "def transform(grid):
    """Encode T objects by orientation in the fixed 3x6 ARC output."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            minr = min(y for y, x in cells); maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells); maxc = max(x for y, x in cells)
            if len(cells) == 4 and maxr-minr == 1 and maxc-minc == 2:
                # code 3: stem above; code 1: stem below
                color = 3 if sum(y == minr for y, x in cells) == 1 else 1
                objects.append((minr, minc, color))
    # provisional output locations are filled by a deterministic spatial map
    out = [[0]*6 for _ in range(3)]
    for i, (r, c, color) in enumerate(sorted(objects)):
        out[min(2, i // 3)][(i % 3) + (0 if color == 3 else 3)] = color
    return out
